function AutoChessMode.prototype.calculateRarityChancesByStageLevel(self, stageLevel)
    local chances = __TS__New(Map)
    if stageLevel <= 1 then
        chances:set(____exports.ChessRarity.COMMON, 100)
    elseif stageLevel == 2 then
        chances:set(____exports.ChessRarity.COMMON, 80)
        chances:set(____exports.ChessRarity.UNCOMMON, 20)
    elseif stageLevel == 3 then
        chances:set(____exports.ChessRarity.COMMON, 75)
        chances:set(____exports.ChessRarity.UNCOMMON, 25)
    elseif stageLevel == 4 or stageLevel == 5 then
        chances:set(____exports.ChessRarity.COMMON, 55)
        chances:set(____exports.ChessRarity.UNCOMMON, 30)
        chances:set(____exports.ChessRarity.RARE, 15)
    elseif stageLevel == 6 then
        chances:set(____exports.ChessRarity.COMMON, 45)
        chances:set(____exports.ChessRarity.UNCOMMON, 33)
        chances:set(____exports.ChessRarity.RARE, 20)
        chances:set(____exports.ChessRarity.EPIC, 2)
    elseif stageLevel == 7 or stageLevel == 8 then
        chances:set(____exports.ChessRarity.COMMON, 30)
        chances:set(____exports.ChessRarity.UNCOMMON, 40)
        chances:set(____exports.ChessRarity.RARE, 25)
        chances:set(____exports.ChessRarity.EPIC, 5)
    elseif stageLevel == 9 or stageLevel == 10 then
        chances:set(____exports.ChessRarity.COMMON, 25)
        chances:set(____exports.ChessRarity.UNCOMMON, 35)
        chances:set(____exports.ChessRarity.RARE, 30)
        chances:set(____exports.ChessRarity.EPIC, 8)
        chances:set(____exports.ChessRarity.LEGENDARY, 2)
    else
        chances:set(____exports.ChessRarity.COMMON, 25)
        chances:set(____exports.ChessRarity.UNCOMMON, 35)
        chances:set(____exports.ChessRarity.RARE, 30)
        chances:set(____exports.ChessRarity.EPIC, 8)
        chances:set(____exports.ChessRarity.LEGENDARY, 2)
    end
    return chances
end
function AutoChessMode.prototype.unlockRandomPieceAfterVictory(self, playerId)
