function AutoChessMode.prototype.getStageDescription(self, config)
    local typeNames = {
        normal_battle = "普通战斗",
        elite_battle = "精英战斗",
        event = "事件",
        event_evacuate = "事件/撤离",
        boss = "Boss"
    }
    local typeName = typeNames[config.primaryNodeType] or config.primaryNodeType
    local monsterCount = StageConfigManager:rollMonsterCount(config.stageId)
    local totalCount = monsterCount.normalCount + (monsterCount.specialCount or 0)
    return ((tostring(typeName) .. " | 怪物数量: ") .. tostring(totalCount)) .. "个"
end
function AutoChessMode.prototype.handleWaveStageSelection(self, playerId, stageId)
    local nodeId = self:stageIdToNodeId(stageId)
    if not nodeId or not self.availableStages:has(nodeId) then
        print((("[AutoChessMode] ERROR: 关卡未解锁或无效 - stageId: " .. stageId) .. ", nodeId: ") .. nodeId)
        print("[AutoChessMode] 可用关卡: " .. table.concat(
            __TS__ArrayFrom(self.availableStages),
            ", "
        ))
        CustomGameEventManager:Send_ServerToPlayer(
            PlayerResource:GetPlayer(playerId),
            "autochess_wave_stage_ack",
            {stageId = stageId, success = false, message = "关卡未解锁，请先完成前置关卡"}
        )
        return
    end
    local stageIdNum = __TS__ParseInt(stageId)
    local stageConfig = StageConfigManager:getStageConfig(stageIdNum)
    if not stageConfig then
        print("[AutoChessMode] ERROR: 无效的关卡ID: " .. stageId)
        CustomGameEventManager:Send_ServerToPlayer(
            PlayerResource:GetPlayer(playerId),
            "autochess_wave_stage_ack",
            {stageId = stageId, success = false, message = "无效的关卡ID"}
        )
        return
    end
    print("[AutoChessMode] ========== 玩家选择关卡 ==========")
    print(((((("[AutoChessMode] Player " .. tostring(playerId)) .. " selected stage: ") .. stageId) .. " (") .. stageConfig.primaryNodeType) .. ")")
    if self.phaseTimer then
        Timers:RemoveTimer(self.phaseTimer)
        self.phaseTimer = nil
        print("[AutoChessMode] 已停止当前阶段计时器")
    end
    self:stopAllBattles()
    print("[AutoChessMode] 已清理所有棋子（包括玩家棋子），新关卡时会重新创建")
    self:resetWaveSettlementState()
    self.currentWaveStageSelection = stageId
    print("[AutoChessMode] 📝 已设置 currentWaveStageSelection = " .. self.currentWaveStageSelection)
    CustomGameEventManager:Send_ServerToAllClients("autochess_wave_stage_ack", {
        playerId = playerId,
        stageId = stageId,
        success = true,
        stageName = "关卡" .. stageId,
        stageType = stageConfig.primaryNodeType,
        message = ("已选择关卡" .. stageId) .. "，准备开始..."
    })
    print("[AutoChessMode] 开始10秒准备阶段...")
    self:startPreparationCountdown(playerId, stageIdNum)
end
function AutoChessMode.prototype.startPreparationCountdown(self, playerId, stageId)
    local PREP_TIME = 10
    local timeLeft = PREP_TIME
    if self.gameState.currentRound == 0 or self.gameState.currentRound == 1 then
        print("[AutoChessMode] 第一回合：设置准备阶段状态")
        self.gameState.currentPhase = ____exports.RoundPhase.PREPARATION
        self.gameState.phaseTimeLeft = PREP_TIME
        for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
            local pid = ____value[1]
            local playerState = ____value[2]
            if playerState.isAlive then
                self.battleSystem:movePlayerToSpectatorArea(pid)
            end
        end
        self.battleSystem:recreateHexBoard()
        self:createPlayerInitialPieces()
        print("[AutoChessMode] 准备阶段：创建敌人棋子（禁用攻击）...")
        self:createEnemyPiecesForPreparation(stageId)
        CustomGameEventManager:Send_ServerToAllClients("show_inventory", {})
        print("[AutoChessMode] ✅ 第一回合准备阶段状态已设置，棋子已创建")
    else
        print("[AutoChessMode] 准备阶段：创建敌人棋子（禁用攻击）...")
        self:createEnemyPiecesForPreparation(stageId)
    end
    CustomGameEventManager:Send_ServerToAllClients("autochess_preparation_started", {timeLeft = timeLeft, stageId = stageId})
    print(("[AutoChessMode] 创建准备阶段倒计时计时器，初始时间: " .. tostring(timeLeft)) .. "秒")
    local autoDeployTriggered = false
    local countdownTimer = Timers:CreateTimer(
        1,
        function()
            timeLeft = timeLeft - 1
            print(((((("[AutoChessMode] 准备阶段倒计时: " .. tostring(timeLeft)) .. "秒 (stageId: ") .. tostring(stageId)) .. ", playerId: ") .. tostring(playerId)) .. ")")
            if timeLeft == 3 and not autoDeployTriggered then
                autoDeployTriggered = true
                print("[AutoChessMode] ⏰ 倒计时剩余3秒，检查是否需要自动部署...")
                for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
                    local pid = ____value[1]
                    local playerState = ____value[2]
                    if playerState.isAlive then
                        local deployedPieces = self.battleSystem:getPlayerPieces(pid)
                        if #deployedPieces == 0 then
                            print(("[AutoChessMode] 玩家 " .. tostring(pid)) .. " 未部署棋子，准备自动部署...")
                            self:autoDeployFromBench(pid)
                        else
                            print(((("[AutoChessMode] 玩家 " .. tostring(pid)) .. " 已有 ") .. tostring(#deployedPieces)) .. " 个棋子，跳过自动部署")
                        end
                    end
                end
            end
            CustomGameEventManager:Send_ServerToAllClients("autochess_preparation_countdown", {timeLeft = timeLeft, stageId = stageId})
            if timeLeft <= 0 then
                print("[AutoChessMode] ========== 准备阶段结束，开始生成怪物并战斗 ==========")
                print(((("[AutoChessMode] 调用 startBattleWithStage(playerId: " .. tostring(playerId)) .. ", stageId: ") .. tostring(stageId)) .. ")")
                self:startBattleWithStage(playerId, stageId)
                return nil
            end
            return 1
        end
    )
    if not countdownTimer then
        print("[AutoChessMode] ❌ 错误：倒计时计时器创建失败！")
    else
        print("[AutoChessMode] ✅ 倒计时计时器创建成功")
    end
end
